import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";

export default function ApplicationForm(props) {
  const { id } = useParams();
  const [scholarship, setScholarship] = useState(null);
  const [formData, setFormData] = useState({
    name: "",
    dob: "",
    fathername: "",
    mothername: "",
    email: "",
    institute: "",
    rollNumber: "",
    cgpa: "",
    marks: "",
    semMarksheet: null,
    boardmarksheet: null,
  });
  const [message, setMessage] = useState("");

  useEffect(() => {
    const fetchScholarship = async () => {
      try {
        const res = await fetch(
          `${props.scholarshipendpoint}/${id}`
        );
        const data = await res.json();
        if (res.ok) setScholarship(data.data);
      } catch (err) {
        console.error("Error fetching scholarship:", err);
      }
    };
    fetchScholarship();
  }, [id]);

  // Handle form field change
  const handleChange = (e) => {
    const { name, value, files } = e.target;
    setFormData({
      ...formData,
      [name]: files ? files[0] : value,
    });
  };

  // Handle form submit
  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    try {
      const formDataToSend = new FormData();
      for (let key in formData) {
        formDataToSend.append(key, formData[key]);
      }
      formDataToSend.append("scholarship_id", id);

      const res = await fetch(
        `${process.env.REACT_APP_BACKEND_URL}/api/scholarship/apply`,
        {
          method: "POST",
          body: formDataToSend,
        }
      );

      const data = await res.json();
      if (res.ok) {
        setMessage("Application submitted successfully!");
        setFormData({
          name: "",
          email: "",
          rollNumber: "",
          course: "",
          incomeCertificate: null,
          marksheet: null,
        });
      } else {
        setMessage(data.message || "Failed to submit application.");
      }
    } catch (err) {
      console.error("Error submitting application:", err);
      setMessage("Server error. Please try again later.");
    }
  };

  return (
    <div
      className="container py-5"
      style={{ marginTop: "100px", maxWidth: "800px" }}
    >
      <div className="card shadow p-4">
        <h2 className="text-center text-danger fw-bold mb-4">
          Scholarship Application Form
        </h2>

        {scholarship && (
          <div className="mb-4 text-center">
            <h4 className="fw-semibold">{scholarship.title}</h4>
            <p className="text-muted">
              Deadline:{" "}
              {new Date(scholarship.deadline).toLocaleDateString("en-GB", {
                day: "2-digit",
                month: "long",
                year: "numeric",
              })}
            </p>
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="mb-3">
            <label className="form-label fw-semibold">Full Name</label>
            <input
              type="text"
              className="form-control"
              name="name"
              value={formData.name}
              onChange={handleChange}
              required
              placeholder="Enter your full name"
            />
          </div>

          <div className="mb-3">
            <label className="form-label fw-semibold">Father Name</label>
            <input
              type="text"
              className="form-control"
              name="name"
              value={formData.name}
              onChange={handleChange}
              required
              placeholder="Enter your father's name"
            />
          </div>
          <div className="mb-3">
            <label className="form-label fw-semibold">Mother Name</label>
            <input
              type="text"
              className="form-control"
              name="name"
              value={formData.name}
              onChange={handleChange}
              required
              placeholder="Enter your mother's name"
            />
          </div>

          <div className="mb-3">
            <label className="form-label fw-semibold">Email</label>
            <input
              type="email"
              className="form-control"
              name="email"
              value={formData.email}
              onChange={handleChange}
              required
              placeholder="Enter your email"
            />
          </div>

          <div className="mb-3">
            <label className="form-label fw-semibold">Institute</label>
            <input
              type="text"
              className="form-control"
              name="name"
              value={formData.name}
              onChange={handleChange}
              required
              placeholder="Enter your institute's name"
            />
          </div>

          <div className="row">
            <div className="col-md-6 mb-3">
              <label className="form-label fw-semibold">Roll Number</label>
              <input
                type="text"
                className="form-control"
                name="rollNumber"
                value={formData.rollNumber}
                onChange={handleChange}
                required
                placeholder="Enter roll number"
              />
            </div>
            <div className="col-md-6 mb-3">
              <label className="form-label fw-semibold">Course</label>
              <input
                type="text"
                className="form-control"
                name="course"
                value={formData.course}
                onChange={handleChange}
                required
                placeholder="Enter your course"
              />
            </div>
          </div>

          <div className="row">
            <div className="col-md-6 mb-3">
              <label className="form-label fw-semibold">CGPA</label>
              <input
                type="text"
                className="form-control"
                name="rollNumber"
                value={formData.rollNumber}
                onChange={handleChange}
                required
                placeholder="Current CGPA"
              />
            </div>
            <div className="col-md-6 mb-3">
              <label className="form-label fw-semibold">12th marks (%)</label>
              <input
                type="text"
                className="form-control"
                name="course"
                value={formData.course}
                onChange={handleChange}
                required
                placeholder="12th marks"
              />
            </div>
          </div>

          <div className="mb-3">
            <label className="form-label fw-semibold">
              Upload Semester Marksheet (PDF)
            </label>
            <input
              type="file"
              className="form-control"
              name="incomeCertificate"
              accept=".pdf"
              onChange={handleChange}
              required
            />
          </div>

          <div className="mb-4">
            <label className="form-label fw-semibold">
              Upload 12th Marksheet (PDF)
            </label>
            <input
              type="file"
              className="form-control"
              name="marksheet"
              accept=".pdf"
              onChange={handleChange}
              required
            />
          </div>

          <div className="mb-4">
            <label className="form-label fw-semibold">
              Upload Category Certificate (PDF)
            </label>
            <input
              type="file"
              className="form-control"
              name="marksheet"
              accept=".pdf"
              onChange={handleChange}
              required
            />
          </div>

          <button
            type="submit"
            className="btn btn-danger w-100 fw-semibold py-2"
          >
            Submit Application
          </button>
        </form>

        {message && (
          <div
            className={`alert mt-4 text-center ${
              message.includes("success")
                ? "alert-success"
                : "alert-danger"
            }`}
            role="alert"
          >
            {message}
          </div>
        )}
      </div>
    </div>
  );
}
